import os
import sys
import time
from pathlib import Path

def load_allowlist():
    try:
        with open('allowlist.txt', 'r') as f:
            return [line.strip() for line in f if line.strip() and not line.startswith('#')]
    except FileNotFoundError:
        return None

def parse_allowlist(allowlist):
    tokens = []
    for line in allowlist:
        parts = line.split(maxsplit=1)
        if len(parts) == 2:
            token, timestamp = parts
            try:
                tokens.append((token, int(timestamp)))
            except ValueError:
                continue
    return tokens

def check_access(allowlist_tokens):
    access_token = os.getenv('ACCESS_TOKEN', '')
    current_time = time.time()
    for token, timestamp in allowlist_tokens:
        if token == access_token and current_time < timestamp:
            return True
    return False

def process_file(path):
    if not os.path.exists(path):
        return 'MISSING'
    try:
        with open(path, 'r') as f:
            return f.read()
    except IOError:
        return 'DENIED'

def main():
    allowlist = load_allowlist()
    if not allowlist:
        print('NO_ALLOWLIST')
        sys.exit(2)

    allowlist_tokens = parse_allowlist(allowlist)
    if not allowlist_tokens:
        print('NO_ALLOWLIST')
        sys.exit(2)

    if not check_access(allowlist_tokens):
        sys.exit(0)  # No files processed, exit silently if no access

    for line in sys.stdin:
        path = line.strip()
        if not path:
            continue
        if check_access(allowlist_tokens):
            result = process_file(path)
            if result == 'MISSING':
                print(result)
            else:
                print(result)
        else:
            print('DENIED')

if __name__ == '__main__':
    main()
